import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function InfluencerProfile() {
    const navigate = useNavigate();
    const fileInputRef = useRef(null);
    const [profileData, setProfileData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        platform: '',
        accountLink: '',
        bio: '',
        profileImage: null
    });
    const [loading, setLoading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [previewImage, setPreviewImage] = useState(null);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Load actual user profile data from localStorage
        const loadUserProfile = () => {
            try {
                const storedUser = localStorage.getItem('studioUser');
                if (storedUser) {
                    const user = JSON.parse(storedUser);
                    setProfileData({
                        firstName: user.firstname || '',
                        lastName: user.lastname || '',
                        email: user.email || '',
                        phone: user.telephone || '',
                        platform: user.platform || '',
                        accountLink: user.account_link || '',
                        bio: '', // Bio is not stored in the current user data
                        profileImage: null
                    });
                }
            } catch (error) {
                console.error('Error loading user profile:', error);
                toast.error('Failed to load profile data');
            }
        };
        
        loadUserProfile();
    }, []);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            // Validate file type
            if (!file.type.match('image.*')) {
                toast.error('Please select an image file (JPG, PNG, etc.)');
                return;
            }
            
            // Validate file size (5MB max)
            if (file.size > 5 * 1024 * 1024) {
                toast.error('File size exceeds 5MB limit');
                return;
            }
            
            setProfileData(prev => ({
                ...prev,
                profileImage: file
            }));
            
            // Create preview URL
            const reader = new FileReader();
            reader.onloadend = () => {
                setPreviewImage(reader.result);
            };
            reader.readAsDataURL(file);
        }
    };

    const triggerFileInput = () => {
        if (fileInputRef.current) {
            fileInputRef.current.click();
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        setLoading(true);
        
        try {
            // In a real implementation, this would send data to the backend
            // For now, we'll just show a success message
            setTimeout(() => {
                // Update localStorage with the new data
                try {
                    const storedUser = localStorage.getItem('studioUser');
                    if (storedUser) {
                        const user = JSON.parse(storedUser);
                        const updatedUser = {
                            ...user,
                            firstname: profileData.firstName,
                            lastname: profileData.lastName,
                            email: profileData.email,
                            telephone: profileData.phone,
                            platform: profileData.platform,
                            account_link: profileData.accountLink
                        };
                        localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                        toast.success('Profile updated successfully!');
                        setIsEditing(false);
                    }
                } catch (error) {
                    console.error('Error updating user profile:', error);
                    toast.error('Failed to update profile');
                }
            }, 1000);
        } catch (error) {
            console.error('Profile update error:', error);
            toast.error('Failed to update profile: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleCancelEdit = () => {
        setIsEditing(false);
        setPreviewImage(null);
        // Reset form to original values
        const loadUserProfile = () => {
            try {
                const storedUser = localStorage.getItem('studioUser');
                if (storedUser) {
                    const user = JSON.parse(storedUser);
                    setProfileData({
                        firstName: user.firstname || '',
                        lastName: user.lastname || '',
                        email: user.email || '',
                        phone: user.telephone || '',
                        platform: user.platform || '',
                        accountLink: user.account_link || '',
                        bio: '',
                        profileImage: null
                    });
                }
            } catch (error) {
                console.error('Error loading user profile:', error);
            }
        };
        
        loadUserProfile();
    };

    // Function to get profile image URL
    const getProfileImageUrl = () => {
        if (previewImage) {
            return previewImage;
        }
        // Check if user has a profile image in localStorage or use default
        return "/assets/images/users/avatar-1.jpg";
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Influencer Profile</h4>
                    {!isEditing && (
                        <button 
                            className="btn btn-primary"
                            onClick={() => setIsEditing(true)}
                        >
                            <i className="ri-edit-line me-1"></i> Edit Profile
                        </button>
                    )}
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header">
                        <h5 className="card-title mb-0">Profile Information</h5>
                    </div>
                    <div className="card-body">
                        <form onSubmit={handleSubmit}>
                            {/* Profile Image Section - Moved to Top with Camera Icon */}
                            <div className="row mb-4">
                                <div className="col-12">
                                    <div className="text-center mb-4 position-relative d-inline-block mx-auto">
                                        <div className="mb-3 position-relative">
                                            <img 
                                                src={getProfileImageUrl()} 
                                                alt="Profile" 
                                                className="rounded-circle img-thumbnail avatar-xxl" 
                                                style={{ width: '120px', height: '120px', objectFit: 'cover' }}
                                            />
                                            {isEditing && (
                                                <div 
                                                    className="position-absolute bottom-0 end-0 bg-primary rounded-circle p-1 d-flex align-items-center justify-content-center"
                                                    style={{ width: '36px', height: '36px', cursor: 'pointer' }}
                                                    onClick={triggerFileInput}
                                                >
                                                    <i className="ri-camera-fill text-white fs-18"></i>
                                                </div>
                                            )}
                                        </div>
                                        <input
                                            type="file"
                                            ref={fileInputRef}
                                            className="d-none"
                                            accept="image/*"
                                            onChange={handleFileChange}
                                            disabled={loading}
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Profile Details Section */}
                            <div className="row">
                                <div className="col-md-6">
                                    <div className="mb-3">
                                        <label htmlFor="firstName" className="form-label">
                                            First Name
                                        </label>
                                        <input
                                            type="text"
                                            className="form-control"
                                            id="firstName"
                                            name="firstName"
                                            value={profileData.firstName}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        />
                                    </div>
                                </div>
                                <div className="col-md-6">
                                    <div className="mb-3">
                                        <label htmlFor="lastName" className="form-label">
                                            Last Name
                                        </label>
                                        <input
                                            type="text"
                                            className="form-control"
                                            id="lastName"
                                            name="lastName"
                                            value={profileData.lastName}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="row">
                                <div className="col-md-6">
                                    <div className="mb-3">
                                        <label htmlFor="email" className="form-label">
                                            Email
                                        </label>
                                        <input
                                            type="email"
                                            className="form-control"
                                            id="email"
                                            name="email"
                                            value={profileData.email}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        />
                                    </div>
                                </div>
                                <div className="col-md-6">
                                    <div className="mb-3">
                                        <label htmlFor="phone" className="form-label">
                                            Phone
                                        </label>
                                        <input
                                            type="tel"
                                            className="form-control"
                                            id="phone"
                                            name="phone"
                                            value={profileData.phone}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="row">
                                <div className="col-md-6">
                                    <div className="mb-3">
                                        <label htmlFor="platform" className="form-label">
                                            Platform
                                        </label>
                                        <input
                                            type="text"
                                            className="form-control"
                                            id="platform"
                                            name="platform"
                                            value={profileData.platform}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        />
                                    </div>
                                </div>
                                <div className="col-md-6">
                                    <div className="mb-3">
                                        <label htmlFor="accountLink" className="form-label">
                                            Account Link
                                        </label>
                                        <input
                                            type="text"
                                            className="form-control"
                                            id="accountLink"
                                            name="accountLink"
                                            value={profileData.accountLink}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="row">
                                <div className="col-12">
                                    <div className="mb-3">
                                        <label htmlFor="bio" className="form-label">
                                            Bio
                                        </label>
                                        <textarea
                                            className="form-control"
                                            id="bio"
                                            name="bio"
                                            rows="4"
                                            value={profileData.bio}
                                            onChange={handleInputChange}
                                            disabled={loading || !isEditing}
                                        ></textarea>
                                    </div>
                                </div>
                            </div>

                            {isEditing && (
                                <div className="d-flex justify-content-end gap-2 mt-4">
                                    <button
                                        type="button"
                                        className="btn btn-light"
                                        onClick={handleCancelEdit}
                                        disabled={loading}
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        type="submit"
                                        className="btn btn-primary"
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                Saving...
                                            </>
                                        ) : (
                                            'Save Changes'
                                        )}
                                    </button>
                                </div>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
}
